  q: 'The function $V(x,y,z) = 3ax - by + bz$, with $a$ and $b$ constants of suitable size, describes the electrostatic potential in a region of space. What is the charge $Q$ present inside a sphere of radius $R$ and center in the origin of cartesian axes?',
