  topic: 'Electric Field and Matter',
  q: 'A charged plane capacitor with plates parallel to the $yz$ plane is filled with a dielectric material whose polarization vector is $\\mathbf{P} = 2\\mathbf{i} - 4\\mathbf{j} + 8\\mathbf{k}\\,(\\text{C/m}^2)$. How many are the charge densities of surface polarization $\\sigma_p$ and volume $\\rho_p$? If the charges on the capacitor plates are homogeneously distributed with constant charge density $\\sigma_0$, is the dielectric isotropic?',
