    '$\\mathbf{B}(\\mathbf{r}) = (\\mu_0 I/4\\pi)\\oint ds^\\prime\\times(\\mathbf{r}-\\mathbf{r}^\\prime)/|\\mathbf{r}-\\mathbf{r}^\\prime|^3$',
    '$\\mathbf{B}(\\mathbf{r}) = (I/4\\pi\\mu_0)\\oint ds^\\prime\\times(\\mathbf{r}-\\mathbf{r}^\\prime)/|\\mathbf{r}-\\mathbf{r}^\\prime|^3$',
