    '$\\mathbf{B} = 3ay\\,\\mathbf{i},\\; \\mathbf{E} = -2b\\,\\mathbf{i} - 3ayt\\,\\mathbf{k},\\; \\mathbf{j}_s = \\varepsilon_0 3ay\\,\\mathbf{k}$',
